                comp, stack = [], [(r, c)]
                seen.add((r, c))
                while stack:
                    rr, cc = stack.pop()
                    comp.append((rr, cc))
                    for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                        if (0 <= nr < h and 0 <= nc < w and
                                grid[nr][nc] not in (0, 5) and (nr, nc) not in seen):
                            seen.add((nr, nc))
                            stack.append((nr, nc))
                comps.append(comp)

    # Each straight run of 5s extends the adjacent colored pattern along the run.
    for horizontal in (True, False):
        fixed_limit, run_limit = (h, w) if horizontal else (w, h)
        for fixed in range(fixed_limit):
            pos = 0
            while pos < run_limit:
                r, c = (fixed, pos) if horizontal else (pos, fixed)
                if grid[r][c] != 5:
                    pos += 1
                    continue
                start = pos
                while pos + 1 < run_limit:
                    nr, nc = (fixed, pos + 1) if horizontal else (pos + 1, fixed)
                    if grid[nr][nc] != 5:
                        break
                    pos += 1
                end = pos

                candidates = []
                for comp in comps:
                    rs = [p[0] for p in comp]
                    cs = [p[1] for p in comp]
                    if horizontal:
                        adjacent = max(rs) == fixed - 1 or min(rs) == fixed + 1
                        overlaps = min(cs) <= end and max(cs) >= start
                    else:
                        adjacent = max(cs) == fixed - 1 or min(cs) == fixed + 1
                        overlaps = min(rs) <= end and max(rs) >= start
                    if adjacent and overlaps:
                        candidates.append(comp)
                if candidates:
                    comp = min(candidates, key=len)
                    if horizontal:
                        # Use the seed column aligned with the start of the 5-run.
                        seed_col = min(comp, key=lambda p: abs(p[1] - start))[1]
                        for rr, cc in comp:
                            if cc == seed_col:
                                for target_c in range(start, end + 1):
                                    out[rr][target_c] = grid[rr][cc]
                    else:
                        # Tile the seed rows, aligning its last row with the run's end.
                        lo = min(r for r, c in comp)
                        hi = max(r for r, c in comp)
                        period = hi - lo + 1
                        for target_r in range(start, end + 1):
